-- 86 The Long Corridor: only three halls exist at a time. The hall the
-- traveller is in and one either side are streamed in (Scene.load_additive),
-- each its own scene with its own wall painting and torches; a hall two
-- behind is dropped (Scene.unload). Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/86-the-long-corridor.scene"
local W = 1280.0
local HALLS = 8
local captions = true
local walker, camera, status
local x, t = 0, 0
local loaded = {}

local function hall(k)
    return "scenes/corridor/hall_" .. (k % HALLS) .. ".scene"
end

function init(entity)
    walker = Entity.find_by_name("Walker")
    camera = Entity.find_by_name("Camera")
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    local speed = Input.is_key_pressed("Space") and 520 or 140
    t = t + dt
    x = x + speed * dt
    local bob = math.abs(math.sin(t * speed * 0.045)) * 6
    Transform.set_position(walker, x, -240 + bob)
    Transform.set_position(camera, x + 160, 0)
    -- The hall the traveller is in, and one either side.
    local r = math.floor((x + W / 2) / W)
    for k = math.max(0, r - 1), r + 1 do
        if not loaded[k] then loaded[k] = Scene.load_additive(hall(k), k * W, 0) end
    end
    for k, h in pairs(loaded) do
        if k < r - 1 or k > r + 1 then
            Scene.unload(h)
            loaded[k] = nil
        end
    end
    local parts = {}
    for k = math.max(0, r - 1), r + 1 do
        local h = loaded[k]
        local s = h and Scene.status(h) or "-"
        local p = h and math.floor(Scene.progress(h) * 100 + 0.5) or 0
        parts[#parts + 1] = string.format("hall %d %s%s", k, s, s == "loading" and (" " .. p .. "%") or "")
    end
    UI.set_text(status, table.concat(parts, "     "))
end
